pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract so the selfdestruct payout is observable
        vm.deal(address(c), amount);

        address owner = c.smartfix_owner();
        uint256 ownerBalBefore = owner.balance;

        // drive c through sudicideAnyone from the fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        uint256 ownerBalAfter = owner.balance;

        // GENERAL RULE: for EVERY actor, either the call reverts (non-owner),
