pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the funding amount in a wide admissible domain
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the victim contract so the selfdestruct payout is observable
        vm.deal(address(c), amount);
        uint256 preContractBalance = address(c).balance;

        // fuzzed actor drives c through the entry point; a non-owner call reverts,
        // an owner call succeeds and must pay the ENTIRE balance to the caller
        address actor = address(uint160(bound(uint160(msg.sender), 2, type(uint160).max)));

        // record balances before the call for both possible outcomes
        uint256 preCallerBalance = actor.balance;
        uint256 preOwnerBalance = c.smartfix_owner().balance;

        vm.prank(actor);
        try c.sudicideAnyone() {
            // Success path (actor == owner): the caller must receive the payout and
            // the contract must be drained to zero.
            assertTrue(
                actor.balance == preCallerBalance + preContractBalance && address(c).balance == 0
            );
        } catch {
            // Revert path (actor != owner): nothing changes anywhere.
            assertTrue(
                address(c).balance == preContractBalance
                    && actor.balance == preCallerBalance
                    && c.smartfix_owner().balance == preOwnerBalance
            );
        }
    }
}

