        // keep the domain wide: any caller, any funding amount
        vm.assume(actor != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the target contract so a successful selfdestruct moves real value
        vm.deal(address(c), amount);
        uint256 cBefore = address(c).balance;

