pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Keep the domain wide: any amount works (0 is admissible but larger amounts are the interesting ones).
        amount = bound(amount, 1, type(uint256).max / 2);

        address owner = c.smartfix_owner();
        address actor = address(new ActorProxy());

        // Only the stored owner may pass the require; the adversarial actor proxy acts as the owner,
        // so the caller (the proxy) is distinct from the recipient named in the mutant.
        vm.deal(address(c), amount);

        vm.prank(owner);
        (bool ok, ) = address(actor).call(
            abi.encodeWithSignature("destroy(address)", address(c))
        );
        assertTrue(ok);

        // Rule: after a successful destroy, c is gone and its ENTIRE prior balance was credited
        // to the CALLER of sudicideAnyone (the actor proxy), not to anyone else.
        assertTrue(
            address(c).balance == 0 &&
            actor.balance == amount &&
            owner.balance == 0
        );
    }
}

// Minimal proxy that is NOT the owner; it merely relays the destroy call as its own msg.sender.
contract ActorProxy {
    function destroy(address target) external {
        (bool s, ) = target.call(abi.encodeWithSignature("sudicideAnyone()"));
        require(s);
    }
}

