pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        // Admissible domain: caller must be a real, distinct account so the
        // selfdestruct beneficiary is well-defined and cannot be c itself.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1e20);

        // Fund the contract so a successful destruction moves real value.
        vm.deal(address(c), amount);
        uint256 callerBefore = actor.balance;
        uint256 cBefore = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // General rule: a call either reverts (non-owner), or it destroys c,
        // leaving c empty and crediting the caller with exactly c's prior balance.
        assertTrue(!ok || (address(c).balance == 0 && actor.balance == callerBefore + cBefore));
    }
}

