pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 ownerBefore = address(this).balance;
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.sudicideAnyone();
        assertTrue(address(this).balance == ownerBefore + amount);
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function testNonOwnerCannotDestroy() public {
    // The test contract is not smartfix_owner (owner was the deployer of C),
    // so in P the call must revert; in M it succeeds and destroys C.
    (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
    assert(!ok);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  receive() external payable {}
  fallback() external payable {}
  function f() public {
    require(c.smartfix_owner() != msg.sender);
    bool ok;
    (ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
    assert(!ok);
  }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool reverted; try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable { }
}

