contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        bool isOwner = (msg.sender == c.smartfix_owner());
        bool reverted; try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted == !isOwner);
    }
    receive() external payable {}
