contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        address owner = c.smartfix_owner();
        bool reverted;
        c.sudicideAnyone();
        if (owner == address(this)) {
            reverted = false;
        } else {
            // owner path never reverts; non-owner always reverts in original
            bool r;
            try c.sudicideAnyone() { r = false; } catch { r = true; }
            reverted = r;
        }
        assert(reverted == (owner != address(this)));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        assert(reverted == (c.smartfix_owner() != msg.sender));
    }
    receive() external payable {}
}

